const C=window.IA_CONTENT||{faq:[],legal:{}};const SLUG=q=>{let t=q.toLowerCase().replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');if(t.length>80){t=t.slice(0,80);t=t.slice(0,t.lastIndexOf('-')>30?t.lastIndexOf('-'):80)}return t};const LNK=t=>esc(t).replace(/https:\/\/[^\s<]*[^\s<.,;)]/g,u=>`<a class="ck-link" href="${u}" target="_blank" rel="noopener noreferrer">${u.replace(/^https:\/\/(www\.)?/,'')}</a>`);const esc=t=>String(t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const PHASES=[['1','Orientieren & Leistbarkeit','Budget, Eigenkapital, Bonität – was kann ich mir leisten?',x=>['Geld & Vermögen','Orientierung & Leistbarkeit'].includes(x.cat)],['2','Objektprüfung & Kennzahlen','Kaufpreisfaktor, Rendite, Hausgeld – rechnet sich das Objekt?',x=>x.cat==='Objektauswahl & Kaufentscheidung'||(x.cat==='Kapitalanlage & Vermögensaufbau'&&!/AfA|15-%|steuerfrei|nach Steuern/.test(x.q))],['3','Steuern & Cashflow','AfA, Werbungskosten, Sanierungsaufwand, Mieteinnahmen absichern',x=>['Steuern & Werbungskosten','Vermieten & Absicherung'].includes(x.cat)||(x.cat==='Kapitalanlage & Vermögensaufbau'&&/AfA|15-%|steuerfrei|nach Steuern/.test(x.q))],['4','Bankgespräch & Kreditmappe','Zinsbindung, Unterlagen, Kreditmappe – sicher ins Bankgespräch',x=>x.cat==='Finanzierung & Bankenpraxis']];const phaseOf=x=>{const h=PHASES.find(P=>P[3](x));return h?h[0]:'0'};
const faqItem=(x,i)=>`<article data-search="${esc((x.q+' '+x.cat+' '+(x.t||'')).toLowerCase())}"><button class="route-q"><span>${i+1}</span><strong>${esc(x.q)}<em class="wq-tag"></em></strong><b>+</b></button><div class="route-a" hidden>${x.t?`<div class="callout wq-teaser"><strong>Kurz gesagt</strong><p>${esc(x.t)}</p></div>`:''}${(document.querySelector('.wq-kurz')||{}).outerHTML||''}<div class="wq-detail" data-q="${esc(x.q)}" data-hook="${esc(x.hook||'')}"></div><p><a class="ck-link" href="/learn/${SLUG(x.q)}">Antwort als eigene Seite öffnen und teilen</a></p></div></article>`;// Fortlaufend nummeriert in Anzeigereihenfolge; innerhalb einer Phase erst Grundlagen, dann Vertiefung.
