const TB=a=>`<nav class="tool-tabs" aria-label="Werkzeuge">${[['Rechner','/calculators'],['Fristen','/deadlines'],['Szenarien','/scenarios']].map(x=>`<a href="${x[1]}"${a===x[1]?' aria-current="page"':''}>${x[0]}</a>`).join('')}</nav>`;const FI=(id,l,v,st)=>`<label>${l}<input id="${id}" type="number" step="${st||'any'}" value="${v}"></label>`,FD=(id,l,v)=>`<label>${l}<input id="${id}" type="date" value="${v}"></label>`,FC=(id,l,c)=>`<label class="consent"><input type="checkbox" id="${id}"${c?' checked':''}> ${l}</label>`;
